import calendar
from datetime import date, timedelta

_CODES = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
_LIMIT_YEAR = 3000


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    tok = rule.split()
    kind = tok[0]
    res: list[str] = []

    if kind == "DAILY":
        k = int(tok[1])
        d = s
        while len(res) < count:
            res.append(d.isoformat())
            d += timedelta(days=k)
        return res

    if kind == "WEEKLY":
        k = int(tok[1])
        offsets = sorted({_CODES.index(c) for c in tok[2].split(",")})
        monday0 = s - timedelta(days=s.weekday())
        j = 0
        while len(res) < count:
            base = monday0 + timedelta(weeks=k * j)
            if base.year >= _LIMIT_YEAR:
                break
            for off in offsets:
                d = base + timedelta(days=off)
                if d >= s:
                    res.append(d.isoformat())
                    if len(res) >= count:
                        break
            j += 1
        return res

    if kind == "MONTHLY":
        k = int(tok[1])
        idx0 = s.year * 12 + (s.month - 1)
        j = 0
        while len(res) < count:
            y, mi = divmod(idx0 + k * j, 12)
            mo = mi + 1
            if y >= _LIMIT_YEAR:
                break
            dim = calendar.monthrange(y, mo)[1]
            d = None
            if len(tok) == 3:
                day = int(tok[2])
                if day == -1:
                    d = date(y, mo, dim)
                elif 1 <= day <= dim:
                    d = date(y, mo, day)
            else:
                n = int(tok[2])
                wd = _CODES.index(tok[3])
                if n > 0:
                    first = date(y, mo, 1)
                    day = 1 + (wd - first.weekday()) % 7 + 7 * (n - 1)
                    if day <= dim:
                        d = date(y, mo, day)
                else:
                    last = date(y, mo, dim)
                    day = dim - (last.weekday() - wd) % 7
                    d = date(y, mo, day)
            if d is not None and d >= s:
                res.append(d.isoformat())
            j += 1
        return res[:count]

    if kind == "YEARLY":
        k = int(tok[1])
        mm, dd = (int(x) for x in tok[2].split("-"))
        j = 0
        while len(res) < count:
            y = s.year + k * j
            if y >= _LIMIT_YEAR:
                break
            try:
                d = date(y, mm, dd)
            except ValueError:
                d = None
            if d is not None and d >= s:
                res.append(d.isoformat())
            j += 1
        return res[:count]

    raise ValueError(f"unknown rule: {rule}")
